import { test, expect } from '@playwright/test';

test.describe('Print Filtered Table View', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/table-view');
  });

  test('should print a filtered table view with pagination', async ({ page }) => {
    // Set up API interception for table data
    await page.route('**/api/table-data', (route) => {
      route.continue();
    });

    // Set up API interception for pagination
    await page.route('**/api/table-data/page', (route) => {
      route.continue();
    });

    // Set up API interception for filter
    await page.route('**/api/table-data/filter', (route) => {
      route.continue();
    });

    // Verify initial table is visible
    const table = page.getByRole('table');
    await expect(table).toBeVisible();

    // Verify table headers are present
    const headers = page.getByRole('rowheader');
    await expect(headers).toBeVisible();

    // Verify table body contains data
    const rows = page.getByRole('row');
    await expect(rows).toHaveCount(10);

    // Apply filter using getByLabel
    const filterInput = page.getByLabel('Filter by Name');
    await filterInput.fill('John Doe');

    // Verify filter is applied
    const filteredRows = page.getByRole('row');
    await expect(filteredRows).toHaveCount(5);

    // Verify pagination controls are visible
    const pageLinks = page.getByRole('link', { name: /page/i });
    await expect(pageLinks).toBeVisible();

    // Navigate to second page
    const secondPageLink = pageLinks.first();
    await secondPageLink.click();

    // Verify table data is paginated
    const secondPageRows = page.getByRole('row');
    await expect(secondPageRows).toHaveCount(10);

    // Verify table headers are still present
    await expect(headers).toBeVisible();

    // Print the filtered table view
    const printButton = page.getByRole('button', { name: /print/i });
    await printButton.click();

    // Verify print dialog appears
    const printDialog = page.getByRole('dialog', { name: /print/i });
    await expect(printDialog).toBeVisible();

    // Verify print button is present
    const printButton = page.getByRole('button', { name: /print/i });
    await expect(printButton).toBeVisible();

    // Verify print button is enabled
    await expect(printButton).toBeEnabled();

    // Close print dialog
    const closeButton = page.getByRole('button', { name: /close/i });
    await closeButton.click();

    // Verify table is still visible after print
    await expect(table).toBeVisible();
  });

  test('should handle empty table view when no data is available', async ({ page }) => {
    // Set up API interception for table data
    await page.route('**/api/table-data', (route) => {
      route.continue();
    });

    // Set up API interception for filter
    await page.route('**/api/table-data/filter', (route) => {
      route.continue();
    });

    // Set up API interception for pagination
    await page.route('**/api/table-data/page', (route) => {
      route.continue();
    });

    // Verify initial table is visible
    const table = page.getByRole('table');
    await expect(table).toBeVisible();

    // Verify table headers are present
    const headers = page.getByRole('rowheader');
    await expect(headers).toBeVisible();

    // Verify table body is empty
    const rows = page.getByRole('row');
    await expect(rows).toHaveCount(0);

    // Apply filter using getByLabel
    const filterInput = page.getByLabel('Filter by Name');
    await filterInput.fill('');

    // Verify table body remains empty
    await expect(rows).toHaveCount(0);

    // Verify no pagination controls are visible
    const pageLinks = page.getByRole('link', { name: /page/i });
    await expect(pageLinks).not.toBeVisible();

    // Verify print button is disabled
    const printButton = page.getByRole('button', { name: /print/i });
    await expect(printButton).not.toBeEnabled();

    // Verify print dialog does not appear
    const printDialog = page.getByRole('dialog', { name: /print/i });
    await expect(printDialog).not.toBeVisible();

    // Verify table is still visible after empty filter
    await expect(table).toBeVisible();
  });
});
